50	/**
51	 * Registry of subscribers to a single event bus.
52	 *
53	 * @author Colin Decker
54	 */
55	final class SubscriberRegistry {
56	
57	  /**
58	   * All registered subscribers, indexed by event type.
59	   *
60	   * <p>The {@link CopyOnWriteArraySet} values make it easy and relatively lightweight to get an
61	   * immutable snapshot of all current subscribers to an event without any locking.
62	   */
63	  private final ConcurrentMap<Class<?>, CopyOnWriteArraySet<Subscriber>> subscribers =
64	      new ConcurrentHashMap<>();
65	
66	  /** The event bus this registry belongs to. */
67	  @Weak private final EventBus bus;
68	
69	  SubscriberRegistry(EventBus bus) {
70	    this.bus = checkNotNull(bus);
71	  }
72	
73	  /** Registers all subscriber methods on the given listener object. */
74	  void register(Object listener) {
75	    Multimap<Class<?>, Subscriber> listenerMethods = findAllSubscribers(listener);
76	
77	    for (Entry<Class<?>, Collection<Subscriber>> entry : listenerMethods.asMap().entrySet()) {
78	      Class<?> eventType = entry.getKey();
79	      Collection<Subscriber> eventMethodsInListener = entry.getValue();
80	
81	      CopyOnWriteArraySet<Subscriber> eventSubscribers = subscribers.get(eventType);
82	
83	      if (eventSubscribers == null) {
84	        CopyOnWriteArraySet<Subscriber> newSet = new CopyOnWriteArraySet<>();
85	        eventSubscribers =
86	            MoreObjects.firstNonNull(subscribers.putIfAbsent(eventType, newSet), newSet);
87	      }
88	
89	      eventSubscribers.addAll(eventMethodsInListener);
90	    }
91	  }
92	
93	  /** Unregisters all subscribers on the given listener object. */
94	  void unregister(Object listener) {
95	    Multimap<Class<?>, Subscriber> listenerMethods = findAllSubscribers(listener);
96	
97	    for (Entry<Class<?>, Collection<Subscriber>> entry : listenerMethods.asMap().entrySet()) {
98	      Class<?> eventType = entry.getKey();
99	      Collection<Subscriber> listenerMethodsForType = entry.getValue();
100	
101	      CopyOnWriteArraySet<Subscriber> currentSubscribers = subscribers.get(eventType);
102	      if (currentSubscribers == null || !currentSubscribers.removeAll(listenerMethodsForType)) {
103	        // if removeAll returns true, all we really know is that at least one subscriber was
104	        // removed... however, barring something very strange we can assume that if at least one
105	        // subscriber was removed, all subscribers on listener for that event type were... after
106	        // all, the definition of subscribers on a particular class is totally static
107	        throw new IllegalArgumentException(
108	            "missing event subscriber for an annotated method. Is " + listener + " registered?");
109	      }
110	
111	      // don't try to remove the set if it's empty; that can't be done safely without a lock
112	      // anyway, if the set is empty it'll just be wrapping an array of length 0
113	    }
114	  }
115	
116	  @VisibleForTesting
117	  Set<Subscriber> getSubscribersForTesting(Class<?> eventType) {
118	    return MoreObjects.firstNonNull(subscribers.get(eventType), ImmutableSet.<Subscriber>of());
119	  }
120	
121	  /**
122	   * Gets an iterator representing an immutable snapshot of all subscribers to the given event at
123	   * the time this method is called.
124	   */
125	  Iterator<Subscriber> getSubscribers(Object event) {
126	    ImmutableSet<Class<?>> eventTypes = flattenHierarchy(event.getClass());
127	
128	    List<Iterator<Subscriber>> subscriberIterators = newArrayListWithCapacity(eventTypes.size());
129	
130	    for (Class<?> eventType : eventTypes) {
131	      CopyOnWriteArraySet<Subscriber> eventSubscribers = subscribers.get(eventType);
132	      if (eventSubscribers != null) {
133	        // eager no-copy snapshot
134	        subscriberIterators.add(eventSubscribers.iterator());
135	      }
136	    }
137	
138	    return concat(subscriberIterators.iterator());
139	  }
140	
141	  /**
142	   * A thread-safe cache that contains the mapping from each class to all methods in that class and
143	   * all super-classes, that are annotated with {@code @Subscribe}. The cache is shared across all
144	   * instances of this class; this greatly improves performance if multiple EventBus instances are
145	   * created and objects of the same class are registered on all of them.
146	   */
147	  private static final LoadingCache<Class<?>, ImmutableList<Method>> subscriberMethodsCache =
148	      CacheBuilder.newBuilder()
149	          .weakKeys()
150	          .build(CacheLoader.from(SubscriberRegistry::getAnnotatedMethodsNotCached));
151	
152	  /**
153	   * Returns all subscribers for the given listener grouped by the type of event they subscribe to.
154	   */
155	  private Multimap<Class<?>, Subscriber> findAllSubscribers(Object listener) {
156	    Multimap<Class<?>, Subscriber> methodsInListener = HashMultimap.create();
157	    Class<?> clazz = listener.getClass();
158	    for (Method method : getAnnotatedMethods(clazz)) {
159	      Class<?>[] parameterTypes = method.getParameterTypes();
160	      Class<?> eventType = parameterTypes[0];
161	      methodsInListener.put(eventType, Subscriber.create(bus, listener, method));
162	    }
163	    return methodsInListener;
164	  }
165	
166	  private static ImmutableList<Method> getAnnotatedMethods(Class<?> clazz) {
167	    try {
168	      return subscriberMethodsCache.getUnchecked(clazz);
169	    } catch (UncheckedExecutionException e) {
170	      if (e.getCause() instanceof IllegalArgumentException) {
171	        /*
172	         * IllegalArgumentException is the one unchecked exception that we know is likely to happen
173	         * (thanks to the checkArgument calls in getAnnotatedMethodsNotCached). If it happens, we'd
174	         * prefer to propagate an IllegalArgumentException to the caller. However, we don't want to
175	         * simply rethrow an exception (e.getCause()) that may in rare cases have come from another
176	         * thread. To accomplish both goals, we wrap that IllegalArgumentException in a new
177	         * instance.
178	         */
179	        throw new IllegalArgumentException(e.getCause().getMessage(), e.getCause());
180	      }
181	      /*
182	       * If some other exception happened, we just propagate the wrapper
183	       * UncheckedExecutionException, which has the stack trace from this thread and which has its
184	       * cause set to the underlying exception (which may be from another thread). If we someday
185	       * learn that some other exception besides IllegalArgumentException is common, then we could
186	       * add another special case to throw an instance of it, too.
187	       */
188	      throw e;
189	    }
190	  }
191	
192	  private static ImmutableList<Method> getAnnotatedMethodsNotCached(Class<?> clazz) {
193	    Set<? extends Class<?>> supertypes = TypeToken.of(clazz).getTypes().rawTypes();
194	    Map<MethodIdentifier, Method> identifiers = new HashMap<>();
195	    for (Class<?> supertype : supertypes) {
196	      for (Method method : supertype.getDeclaredMethods()) {
197	        if (method.isAnnotationPresent(Subscribe.class) && !method.isSynthetic()) {
198	          // TODO(cgdecker): Should check for a generic parameter type and error out
199	          Class<?>[] parameterTypes = method.getParameterTypes();
200	          checkArgument(
201	              parameterTypes.length == 1,
202	              "Method %s has @Subscribe annotation but has %s parameters. "
203	                  + "Subscriber methods must have exactly 1 parameter.",
204	              method,
205	              parameterTypes.length);
206	
207	          checkArgument(
208	              !parameterTypes[0].isPrimitive(),
209	              "@Subscribe method %s's parameter is %s. "
210	                  + "Subscriber methods cannot accept primitives. "
211	                  + "Consider changing the parameter to %s.",
212	              method,
213	              parameterTypes[0].getName(),
214	              Primitives.wrap(parameterTypes[0]).getSimpleName());
215	
216	          MethodIdentifier ident = new MethodIdentifier(method);
217	          if (!identifiers.containsKey(ident)) {
218	            identifiers.put(ident, method);
219	          }
220	        }
221	      }
222	    }
223	    return ImmutableList.copyOf(identifiers.values());
224	  }
225	
226	  /** Global cache of classes to their flattened hierarchy of supertypes. */
