43	abstract class AbstractDirectedNetworkConnections<N, E> implements NetworkConnections<N, E> {
44	  /** Keys are edges incoming to the origin node, values are the source node. */
45	  final Map<E, N> inEdgeMap;
46	
47	  /** Keys are edges outgoing from the origin node, values are the target node. */
48	  final Map<E, N> outEdgeMap;
