50	  private int selfLoopCount;
51	
52	  AbstractDirectedNetworkConnections(Map<E, N> inEdgeMap, Map<E, N> outEdgeMap, int selfLoopCount) {
53	    this.inEdgeMap = checkNotNull(inEdgeMap);
54	    this.outEdgeMap = checkNotNull(outEdgeMap);
55	    this.selfLoopCount = checkNonNegative(selfLoopCount);
56	    checkState(selfLoopCount <= inEdgeMap.size() && selfLoopCount <= outEdgeMap.size());
