59	  @Override
60	  public Set<N> adjacentNodes() {
61	    return union(predecessors(), successors());
62	  }
63	
64	  @Override
65	  public Set<E> incidentEdges() {
66	    return new AbstractSet<E>() {
67	      @Override
68	      public UnmodifiableIterator<E> iterator() {
69	        Iterable<E> incidentEdges =
70	            (selfLoopCount == 0)
71	                ? concat(inEdgeMap.keySet(), outEdgeMap.keySet())
72	                : union(inEdgeMap.keySet(), outEdgeMap.keySet());
73	        return unmodifiableIterator(incidentEdges.iterator());
74	      }
75	
76	      @Override
77	      public int size() {
78	        return IntMath.saturatedAdd(inEdgeMap.size(), outEdgeMap.size() - selfLoopCount);
79	      }
80	
81	      @Override
82	      public boolean contains(@Nullable Object obj) {
83	        return inEdgeMap.containsKey(obj) || outEdgeMap.containsKey(obj);
84	      }
85	    };
86	  }
87	
88	  @Override
89	  public Set<E> inEdges() {
90	    return unmodifiableSet(inEdgeMap.keySet());
91	  }
92	
93	  @Override
94	  public Set<E> outEdges() {
95	    return unmodifiableSet(outEdgeMap.keySet());
96	  }
