18	
19	import com.google.common.collect.ImmutableSet;
20	import java.util.AbstractSet;
21	import java.util.Set;
22	import org.jspecify.annotations.Nullable;
23	
24	/**
25	 * Abstract base class for an incident edges set that allows different implementations of {@link
26	 * AbstractSet#iterator()}.
27	 */
28	abstract class IncidentEdgeSet<N> extends AbstractSet<EndpointPair<N>> {
29	  final N node;
30	  final ArchetypeGraph<N> graph;
31	  final EdgeType edgeType;
32	
33	  enum EdgeType {
34	    INCOMING, // incoming incident edges only
35	    OUTGOING, // outgoing incident edges only
36	    BOTH // both incoming and outgoing incident edges
37	  }
38	
39	  IncidentEdgeSet(ArchetypeGraph<N> graph, N node, EdgeType edgeType) {
40	    this.graph = graph;
41	    this.node = node;
42	    this.edgeType = edgeType;
43	  }
44	
45	  @Override
46	  public boolean remove(@Nullable Object o) {
47	    throw new UnsupportedOperationException();
48	  }
49	
50	  @Override
51	  public int size() {
52	    if (graph.isDirected()) {
53	      return predecessorsOrEmpty(node).size()
54	          + successorsOrEmpty(node).size()
55	          - (edgeType == EdgeType.BOTH && predecessorsOrEmpty(node).contains(node) ? 1 : 0);
56	    } else {
57	      return graph.adjacentNodes(node).size();
58	    }
59	  }
60	
61	  @Override
62	  public boolean contains(@Nullable Object obj) {
63	    if (!(obj instanceof EndpointPair)) {
64	      return false;
65	    }
66	    EndpointPair<?> endpointPair = (EndpointPair<?>) obj;
67	
68	    if (graph.isDirected() != endpointPair.isOrdered()) {
69	      return false;
70	    }
71	
72	    if (graph.isDirected()) {
73	      Object source = endpointPair.source();
74	      Object target = endpointPair.target();
75	      return (node.equals(source) && successorsOrEmpty(node).contains(target))
76	          || (node.equals(target) && predecessorsOrEmpty(node).contains(source));
77	    } else {
78	      Set<N> adjacent = graph.adjacentNodes(node);
79	      Object nodeU = endpointPair.nodeU();
80	      Object nodeV = endpointPair.nodeV();
81	
82	      return (node.equals(nodeV) && adjacent.contains(nodeU))
83	          || (node.equals(nodeU) && adjacent.contains(nodeV));
84	    }
85	  }
86	
87	  /**
88	   * Returns the predecessors of the given node, or an empty set if this set does not represent
89	   * incoming edges.
90	   */
91	  private Set<N> predecessorsOrEmpty(N node) {
92	    if (edgeType == EdgeType.INCOMING || edgeType == EdgeType.BOTH) {
93	      return graph.predecessors(node);
94	    } else {
95	      return ImmutableSet.of();
96	    }
97	  }
98	
99	  /**
100	   * Returns the successors of the given node, or an empty set if this set does not represent
101	   * outgoing edges.
102	   */
103	  private Set<N> successorsOrEmpty(N node) {
104	    if (edgeType == EdgeType.OUTGOING || edgeType == EdgeType.BOTH) {
105	      return graph.successors(node);
106	    } else {
107	      return ImmutableSet.of();
108	    }
109	  }
110	}
