30	/**
31	 * A map-like data structure that wraps a backing map and caches values while iterating through
32	 * {@link #unmodifiableKeySet()}. By design, the cache is cleared when this structure is mutated. If
33	 * this structure is never mutated, it provides a thread-safe view of the backing map.
34	 *
35	 * <p>The {@link MapIteratorCache} assumes ownership of the backing map, and cannot guarantee
36	 * correctness in the face of external mutations to the backing map. As such, it is <b>strongly</b>
37	 * recommended that the caller does not persist a reference to the backing map (unless the backing
38	 * map is immutable).
39	 *
40	 * <p>This class is tailored toward use cases in common.graph. It is *NOT* a general purpose map.
41	 *
42	 * @author James Sexton
43	 */
44	class MapIteratorCache<K, V> {
45	  private final Map<K, V> backingMap;
46	
47	  /*
48	   * Per JDK: "the behavior of a map entry is undefined if the backing map has been modified after
49	   * the entry was returned by the iterator, except through the setValue operation on the map entry"
50	   * As such, this field must be cleared before every map mutation.
51	   *
52	   * Note about volatile: volatile doesn't make it safe to read from a mutable graph in one thread
53	   * while writing to it in another. All it does is help with _reading_ from multiple threads
54	   * concurrently. For more information, see AbstractNetworkTest.concurrentIteration.
55	   */
56	  private transient volatile @Nullable Entry<K, V> cacheEntry;
57	
58	  MapIteratorCache(Map<K, V> backingMap) {
59	    this.backingMap = checkNotNull(backingMap);
60	  }
61	
62	  @CanIgnoreReturnValue
63	  final @Nullable V put(K key, V value) {
64	    checkNotNull(key);
65	    checkNotNull(value);
66	    clearCache();
67	    return backingMap.put(key, value);
68	  }
69	
70	  @CanIgnoreReturnValue
71	  final @Nullable V remove(Object key) {
72	    checkNotNull(key);
73	    clearCache();
74	    return backingMap.remove(key);
75	  }
76	
77	  final void clear() {
78	    clearCache();
79	    backingMap.clear();
80	  }
81	
82	  @Nullable V get(Object key) {
83	    checkNotNull(key);
84	    V value = getIfCached(key);
85	    // TODO(b/192579700): Use a ternary once it no longer confuses our nullness checker.
86	    if (value == null) {
87	      return getWithoutCaching(key);
88	    } else {
89	      return value;
90	    }
91	  }
92	
93	  final @Nullable V getWithoutCaching(Object key) {
94	    checkNotNull(key);
95	    return backingMap.get(key);
96	  }
97	
98	  final boolean containsKey(@Nullable Object key) {
99	    return getIfCached(key) != null || backingMap.containsKey(key);
100	  }
101	
102	  final Set<K> unmodifiableKeySet() {
103	    return new AbstractSet<K>() {
104	      @Override
105	      public UnmodifiableIterator<K> iterator() {
106	        Iterator<Entry<K, V>> entryIterator = backingMap.entrySet().iterator();
107	
108	        return new UnmodifiableIterator<K>() {
109	          @Override
110	          public boolean hasNext() {
111	            return entryIterator.hasNext();
112	          }
113	
114	          @Override
115	          public K next() {
116	            Entry<K, V> entry = entryIterator.next(); // store local reference for thread-safety
117	            cacheEntry = entry;
118	            return entry.getKey();
119	          }
120	        };
121	      }
122	
123	      @Override
124	      public int size() {
125	        return backingMap.size();
126	      }
127	
128	      @Override
129	      public boolean contains(@Nullable Object key) {
130	        return containsKey(key);
131	      }
132	    };
133	  }
134	
135	  // Internal methods (package-visible, but treat as only subclass-visible)
136	
137	  @SuppressWarnings("ReferenceEquality") // see comment below
138	  @Nullable V getIfCached(@Nullable Object key) {
139	    Entry<K, V> entry = cacheEntry; // store local reference for thread-safety
140	
141	    // Check cache. We use == on purpose because it's cheaper and a cache miss is ok.
142	    if (entry != null && entry.getKey() == key) {
143	      return entry.getValue();
144	    }
145	    return null;
146	  }
147	
148	  void clearCache() {
149	    cacheEntry = null;
150	  }
151	}
